const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const escapeHtml = (value='') => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function researchMarkdown(value=''){
  const lines=String(value).split(/\r?\n/);let html='',list=false;
  const inline=s=>escapeHtml(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\[S(\d+)\]/g,'<button class="evidence-cite" data-cite="$1" title="Open supporting source">S$1</button>');
  for(const raw of lines){const line=raw.trim();const heading=line.match(/^(#{1,3})\s+(.+)/);const bullet=line.match(/^[-*]\s+(.+)/);
    if(heading){if(list){html+='</ul>';list=false}html+=`<h${Math.min(4,heading[1].length+1)}>${inline(heading[2])}</h${Math.min(4,heading[1].length+1)}>`}
    else if(bullet){if(!list){html+='<ul>';list=true}html+=`<li>${inline(bullet[1])}</li>`}
    else if(line){if(list){html+='</ul>';list=false}html+=`<p>${inline(line)}</p>`}
  }
  return html+(list?'</ul>':'');
}
const fmtDate = value => value ? new Date(value).toLocaleString() : '—';
const state = {page:'command', dashboard:null, conversation:sessionStorage.getItem('raven_active_conversation')||null, voice:null, wake:null, wakeEnabled:true, wakeGreeting:false, graph:null, selectedRun:null};
function setActiveConversation(id){state.conversation=id||null;if(id)sessionStorage.setItem('raven_active_conversation',id);else sessionStorage.removeItem('raven_active_conversation');return state.conversation}

async function applyUiAction(action){
  if(!action)return;
  if(action.type==='world_actions'){
    if(state.page!=='world'||!window.RavenGeo)await route('world');
    if(!window.RavenGeo)throw new Error('The World workspace could not open.');
    await window.RavenGeo.apply(action.actions||[]);return;
  }
  if(action.type==='voice_rate'){state.voiceRate=Math.max(.65,Math.min(1.5,(state.voiceRate||1)*(action.direction==='slower'?.85:1.15)));if(state.voice?.audio)state.voice.audio.playbackRate=state.voiceRate;toast(`Speech playback speed: ${Math.round(state.voiceRate*100)}%`);return}
  if(action.type==='sequence'){
    for(const item of action.actions||[])await applyUiAction(item);
    return;
  }
  if(action.type==='navigate'){await route(action.page);return}
  if(action.type==='graph_zoom'){
    if(state.page!=='graph'||!$('#graphCanvas'))await route('graph');
    if(typeof window.ravenGraphZoom==='function')window.ravenGraphZoom(action.direction);
    else toast('Open the Knowledge Graph before using zoom controls.');
    return;
  }
  if(action.type==='graph_control'){
    if(state.page!=='graph'||!$('#graphCanvas'))await route('graph');
    if(typeof window.ravenGraphControl==='function')window.ravenGraphControl(action.direction);
    else toast('Open the Knowledge Graph before moving it.');
    return;
  }
  if(action.type==='graph_filter'){
    const run=()=>typeof window.ravenGraphFilter==='function'?window.ravenGraphFilter(action):toast('Knowledge Graph controls are still loading.');
    if(state.page!=='graph'||!$('#graphCanvas'))await route('graph');run();
    return;
  }
  if(action.type==='external_open'){
    const opened=window.open(action.url,'_blank','noopener,noreferrer');
    if(!opened){inspect('SAFE EXTERNAL LINK',{title:action.label||'External link',url:action.url,note:'Your browser blocked the new tab. Use the link below.'});$('#inspectorBody').insertAdjacentHTML('beforeend',`<a class="primary external-link" href="${escapeHtml(action.url)}" target="_blank" rel="noopener">OPEN ${escapeHtml(action.label||'LINK').toUpperCase()} ↗</a>`)}
    return;
  }
  if(action.type==='youtube_results'){
    $('.inspector-head span').textContent='YOUTUBE OPTIONS';
    $('#inspectorBody').innerHTML=`<div class="eyebrow">CURRENT PUBLIC VIDEO SEARCH</div><h2 class="lens-title">${escapeHtml(action.query)}</h2><p class="subtle">These are verified YouTube links from the current public search index. Opening a result never sends a RAVEN API key.</p><div class="youtube-options">${(action.videos||[]).map((video,i)=>`<a href="${escapeHtml(video.url)}" target="_blank" rel="noopener"><span>${String(i+1).padStart(2,'0')}</span><div><b>${escapeHtml(video.title)}</b><small>${escapeHtml(video.snippet||'Public YouTube result')}</small></div><i>OPEN ↗</i></a>`).join('')||'<p>No verified videos returned.</p>'}</div>`;
  }
}

async function api(path, options={}) {
  if(path==='/chat'&&typeof options.body==='string'&&state.page==='world'&&window.RavenGeo){
    const body=JSON.parse(options.body);body.world_context=window.RavenGeo.context();body.ui_page='world';options={...options,body:JSON.stringify(body)};
  }
  const response = await fetch('/api'+path, {
    credentials:'same-origin',
    headers:{...(options.body instanceof FormData || typeof options.body === 'string' ? {} : {'Content-Type':'application/json'}), ...(options.headers||{})},
    ...options
  });
  if (response.status === 401) { showLogin(); throw new Error('Session expired'); }
  if (!response.ok) {
    const data = await response.json().catch(()=>({detail:response.statusText}));
    throw new Error(typeof data.detail === 'string' ? data.detail : JSON.stringify(data.detail));
  }
  const type=response.headers.get('content-type')||'';
  const payload=type.includes('json') ? await response.json() : await response.text();
  if(!options.deferUiAction)await applyUiAction(payload?.ui_action);
  return payload;
}

